// submit.js — Part 4: Backend Integration
import { useState } from 'react';
import { useStore } from './store';
import { shallow } from 'zustand/shallow';

const selector = (state) => ({ nodes: state.nodes, edges: state.edges });

export const SubmitButton = () => {
  const { nodes, edges } = useStore(selector, shallow);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const response = await fetch('http://localhost:8000/pipelines/parse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges }),
      });

      if (!response.ok) throw new Error(`HTTP error: ${response.status}`);
      const data = await response.json();
      setResult(data);
    } catch (err) {
      setResult({ error: err.message });
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div className="submit-bar">
        <span className="submit-hint">
          {nodes.length} node{nodes.length !== 1 ? 's' : ''} · {edges.length} edge{edges.length !== 1 ? 's' : ''}
        </span>
        <button className="submit-btn" onClick={handleSubmit} disabled={loading}>
          {loading ? (
            <>
              <span style={{ display: 'inline-block', animation: 'spin 1s linear infinite' }}>⟳</span>
              Analyzing…
            </>
          ) : (
            <>▶ Run Pipeline</>
          )}
        </button>
      </div>

      {result && (
        <div className="pipeline-alert-overlay" onClick={() => setResult(null)}>
          <div className="pipeline-alert" onClick={(e) => e.stopPropagation()}>
            {result.error ? (
              <>
                <h3>⚠️ Error</h3>
                <p style={{ color: '#ef4444', fontSize: 13 }}>{result.error}</p>
                <br />
                <button className="alert-close-btn" onClick={() => setResult(null)}>Close</button>
              </>
            ) : (
              <>
                <h3>📊 Pipeline Analysis</h3>
                <div className="alert-stats">
                  <div className="alert-stat">
                    <div className="alert-stat-value">{result.num_nodes}</div>
                    <div className="alert-stat-label">Nodes</div>
                  </div>
                  <div className="alert-stat">
                    <div className="alert-stat-value">{result.num_edges}</div>
                    <div className="alert-stat-label">Edges</div>
                  </div>
                  <div className="alert-stat">
                    <div className={`alert-stat-value ${result.is_dag ? 'dag-true' : 'dag-false'}`}>
                      {result.is_dag ? '✓' : '✗'}
                    </div>
                    <div className="alert-stat-label">Is DAG</div>
                  </div>
                </div>
                <p style={{ fontSize: 12, color: 'var(--text-secondary)', marginBottom: 16 }}>
                  {result.is_dag
                    ? '✅ Valid DAG — pipeline can be executed without circular dependencies.'
                    : '⚠️ Not a DAG — pipeline contains cycles and cannot be executed as-is.'}
                </p>
                <button className="alert-close-btn" onClick={() => setResult(null)}>Close</button>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
};
